/* Generated from Moru UI source. Do not edit. SPDX-License-Identifier: MIT */
:where([data-moru-registry]) .ui-resizable-group {
  min-width: 0;
  max-width: 100%;
  color: var(--ui-text);
  font-family: var(--ui-font-family);
  font-size: var(--ui-type-body-size);
  line-height: var(--ui-type-body-line-height);
  letter-spacing: var(--ui-type-body-letter-spacing);
}
:where([data-moru-registry]) .ui-resizable-group {
  display: flex;
  width: 100%;
  border: var(--ui-border-width) solid var(--ui-border);
  border-radius: calc(var(--ui-radius) + 4px);
  overflow: hidden;
  background: var(--ui-surface);
}
:where([data-moru-registry]) .ui-resizable-group[aria-orientation='vertical'] {
  flex-direction: column;
}
:where([data-moru-registry]) .ui-resizable-panel {
  min-width: 0;
  min-height: 0;
  overflow: auto;
}
:where([data-moru-registry]) .ui-resizable-handle {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  flex: none;
  width: 8px;
  min-width: 8px;
  background: var(--ui-control-hover-bg);
  outline: none;
}
:where([data-moru-registry]) .ui-resizable-handle[aria-orientation='horizontal'] {
  width: 100%;
  min-width: 0;
  height: 8px;
  min-height: 8px;
}
:where([data-moru-registry]) .ui-resizable-handle > span {
  display: flex;
  justify-content: center;
  align-items: center;
  width: 14px;
  height: 26px;
  flex: none;
  border: var(--ui-border-width) solid var(--ui-border);
  border-radius: 4px;
  background: var(--ui-surface);
  color: var(--ui-muted);
  z-index: 1;
}
:where([data-moru-registry]) .ui-resizable-handle[aria-orientation='horizontal'] > span {
  transform: rotate(90deg);
}
:where([data-moru-registry]) .ui-resizable-handle:focus-visible,
:where([data-moru-registry]) .ui-resizable-handle[data-separator='active'] {
  background: var(--ui-focus-ring);
}

'use client'
// Generated from Moru UI source. Do not edit. SPDX-License-Identifier: MIT
import { useI18n } from './_lib/i18n'
import {
  Group,
  Panel,
  Separator,
  type GroupProps,
  type PanelProps,
  type SeparatorProps,
} from 'react-resizable-panels'
import { GripVertical } from 'lucide-react'
import { cn } from './_lib/cn'
import './resizable.css'

export function ResizablePanelGroup({ className, ...props }: GroupProps) {
  return <Group {...props} className={cn('ui-resizable-group', className)} />
}
export function ResizablePanel({ className, ...props }: PanelProps) {
  return <Panel {...props} className={cn('ui-resizable-panel', className)} />
}
export function ResizableHandle({
  className,
  withHandle = true,
  'aria-label': labelProp,
  ...props
}: SeparatorProps & { withHandle?: boolean }) {
  const { t } = useI18n()
  const label = labelProp ?? t('패널 크기 조절')

  return (
    <Separator {...props} aria-label={label} className={cn('ui-resizable-handle', className)}>
      {withHandle && (
        <span>
          <GripVertical size={14} aria-hidden="true" />
        </span>
      )}
    </Separator>
  )
}
export type { GroupProps as ResizablePanelGroupProps, PanelProps as ResizablePanelProps }
